    border: 2px solid #2a2a4a;
    border-radius: 6px;
    cursor: crosshair;
    box-shadow: 0 0 30px rgba(0,255,136,0.12);
  }
  #controls {
    margin-top: 18px;
    display: flex;
    gap: 10px;
    flex-wrap: wrap;
    justify-content: center;
  }
  button {
    padding: 10px 22px;
    border: none;
    border-radius: 22px;
    font-size: 0.95em;
    cursor: pointer;
    transition: all 0.2s ease;
    font-weight: 600;
    letter-spacing: 0.5px;
  }
  #step   { background: #00ff88; color: #0a0a1a; }
  #play   { background: #ff6b6b; color: #fff; }
  #random { background: #ffd93d; color: #0a0a1a; }
  #clear  { background: #6c5ce7; color: #fff; }
  button:hover { transform: scale(1.07); box-shadow: 0 0 18px rgba(255,255,255,0.25); }
  button:active { transform: scale(0.95); }
</style>
</head>
<body>
  <h1>⬡ Conway's Game of Life</h1>
  <canvas id="life" width="400" height="400"></canvas>
  <div id="controls">
    <button id="step">Step</button>
    <button id="play">▶ Play</button>
    <button id="random">Random</button>
    <button id="clear">Clear</button>
  </div>
  <script>
  (function() {
    var W = 50;
    var H = 50;
    var CELL = 8;

    var canvas = document.getElementById('life');
    var ctx = canvas.getContext('2d');

    var grid = new Uint8Array(W * H);
    var nextGrid = new Uint8Array(W * H);

    function draw() {
      ctx.fillStyle = '#0d0d1a';
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      ctx.strokeStyle = '#1a1a2e';
      ctx.lineWidth = 0.5;
      ctx.beginPath();
      for (var x = 0; x <= W; x++) {
        ctx.moveTo(x * CELL + 0.5, 0);
        ctx.lineTo(x * CELL + 0.5, H * CELL);
      }
      for (var y = 0; y <= H; y++) {
        ctx.moveTo(0, y * CELL + 0.5);
        ctx.lineTo(W * CELL, y * CELL + 0.5);
      }
      ctx.stroke();

      ctx.shadowColor = '#00ff88';
      ctx.shadowBlur = 4;
      ctx.fillStyle = '#00ff88';
      for (var y = 0; y < H; y++) {
        for (var x = 0; x < W; x++) {
          if (grid[y * W + x]) {
            ctx.fillRect(x * CELL + 1, y * CELL + 1, CELL - 2, CELL - 2);
          }
        }
      }
      ctx.shadowBlur = 0;
    }

    function countNeighbors(x, y) {
      var count = 0;
      for (var dy = -1; dy <= 1; dy++) {
        for (var dx = -1; dx <= 1; dx++) {
          if (dx === 0 && dy === 0) continue;
          var nx = x + dx;
          var ny = y + dy;
          if (nx >= 0 && nx < W && ny >= 0 && ny < H) {
            count += grid[ny * W + nx];
          }
        }
      }
      return count;
    }

    function computeNext() {
      for (var y = 0; y < H; y++) {
        for (var x = 0; x < W; x++) {
          var idx = y * W + x;
          var n = countNeighbors(x, y);
          if (grid[idx]) {
            nextGrid[idx] = (n === 2 || n === 3) ? 1 : 0;
          } else {
            nextGrid[idx] = (n === 3) ? 1 : 0;
          }
        }
      }
      var temp = grid;
      grid = nextGrid;
      nextGrid = temp;
    }

    window.life = {
      w: W,
      h: H,
      get: function(x, y) {
        if (x < 0 || x >= W || y < 0 || y >= H) return 0;
        return grid[y * W + x];
      },
      set: function(x, y, v) {
        if (x >= 0 && x < W && y >= 0 && y < H) {
          grid[y * W + x] = v ? 1 : 0;
        }
      },
      step: function() {
        computeNext();
        draw();
      },
      clear: function() {
        grid.fill(0);
        draw();
      }
    };

    document.getElementById('step').addEventListener('click', function() {
      window.life.step();
    });

    var playing = false;
    var timer = null;

    document.getElementById('play').addEventListener('click', function() {
      playing = !playing;
      this.textContent = playing ? '⏸ Pause' : '▶ Play';
      if (playing) {
        timer = setInterval(function() {
          window.life.step();
        }, 80);
      } else {
        clearInterval(timer);
      }
    });

    document.getElementById('random').addEventListener('click', function() {
      for (var i = 0; i < W * H; i++) {
        grid[i] = Math.random() < 0.3 ? 1 : 0;
      }
      draw();
    });

    document.getElementById('clear').addEventListener('click', function() {
      window.life.clear();
    });

    var painting = false;
    var lastCellX = -1, lastCellY = -1;

    function getCell(e) {
      var rect = canvas.getBoundingClientRect();
      var scaleX = canvas.width / rect.width;
      var scaleY = canvas.height / rect.height;
      var cx = (e.clientX - rect.left) * scaleX;
      var cy = (e.clientY - rect.top) * scaleY;
      return {
        x: Math.floor(cx / CELL),
        y: Math.floor(cy / CELL)
      };
    }

    function toggleCell(x, y) {
      if (x >= 0 && x < W && y >= 0 && y < H) {
        grid[y * W + x] = grid[y * W + x] ? 0 : 1;
      }
    }

    function drawLine(x0, y0, x1, y1) {
      var dx = Math.abs(x1 - x0);
      var dy = Math.abs(y1 - y0);
      var sx = x0 < x1 ? 1 : -1;
      var sy = y0 < y1 ? 1 : -1;
      var err = dx - dy;
      while (true) {
        toggleCell(x0, y0);
        if (x0 === x1 && y0 === y1) break;
        var e2 = 2 * err;
        if (e2 > -dy) { err -= dy; x0 += sx; }
        if (e2 < dx) { err += dx; y0 += sy; }
      }
    }

    canvas.addEventListener('mousedown', function(e) {
      painting = true;
      var pos = getCell(e);
      toggleCell(pos.x, pos.y);
      lastCellX = pos.x;
      lastCellY = pos.y;
      draw();
    });

    canvas.addEventListener('mousemove', function(e) {
      if (!painting) return;
      var pos = getCell(e);
      if (pos.x !== lastCellX || pos.y !== lastCellY) {
        drawLine(lastCellX, lastCellY, pos.x, pos.y);
        lastCellX = pos.x;
        lastCellY = pos.y;
        draw();
      }
    });

    canvas.addEventListener('mouseup', function() { painting = false; });
    canvas.addEventListener('mouseleave', function() { painting = false; });

    canvas.addEventListener('touchstart', function(e) {
      e.preventDefault();
      painting = true;
      var touch = e.touches[0];
      var pos = getCell(touch);
      toggleCell(pos.x, pos.y);
      lastCellX = pos.x;
      lastCellY = pos.y;
      draw();
    }, { passive: false });

    canvas.addEventListener('touchmove', function(e) {
      e.preventDefault();
      if (!painting) return;
      var touch = e.touches[0];
      var pos = getCell(touch);
      if (pos.x !== lastCellX || pos.y !== lastCellY) {
        drawLine(lastCellX, lastCellY, pos.x, pos.y);
        lastCellX = pos.x;
        lastCellY = pos.y;
        draw();
      }
    }, { passive: false });

    canvas.addEventListener('touchend', function() { painting = false; });

    draw();
  })();
  </script>
</body>
</html>
